SET client_encoding = 'UTF8';
BEGIN;

DROP TABLE IF EXISTS binh_luan CASCADE;
DROP TABLE IF EXISTS dat_phong CASCADE;
DROP TABLE IF EXISTS phong_thue CASCADE;
DROP TABLE IF EXISTS nguoi_dung CASCADE;
DROP TABLE IF EXISTS vi_tri CASCADE;

CREATE TABLE vi_tri (
  id INTEGER PRIMARY KEY,
  ten_vi_tri TEXT,
  tinh_thanh TEXT,
  quoc_gia TEXT,
  hinh_anh TEXT
);

CREATE TABLE nguoi_dung (
  id INTEGER PRIMARY KEY,
  name TEXT,
  email TEXT,
  password TEXT,
  phone TEXT,
  birthday TEXT,
  avatar TEXT,
  gender BOOLEAN,
  role TEXT
);

CREATE TABLE phong_thue (
  id INTEGER PRIMARY KEY,
  ten_phong TEXT,
  khach INTEGER,
  phong_ngu INTEGER,
  giuong INTEGER,
  phong_tam INTEGER,
  mo_ta TEXT,
  gia_tien NUMERIC,
  may_giat BOOLEAN,
  ban_la BOOLEAN,
  tivi BOOLEAN,
  dieu_hoa BOOLEAN,
  wifi BOOLEAN,
  bep BOOLEAN,
  do_xe BOOLEAN,
  ho_boi BOOLEAN,
  ban_ui BOOLEAN,
  ma_vi_tri INTEGER,
  hinh_anh TEXT
);
