CREATE TABLE dat_phong (
  id INTEGER PRIMARY KEY,
  ma_phong INTEGER,
  ngay_den TIMESTAMP,
  ngay_di TIMESTAMP,
  so_luong_khach INTEGER,
  ma_nguoi_dung INTEGER
);

CREATE TABLE binh_luan (
  id INTEGER PRIMARY KEY,
  ma_phong INTEGER,
  ma_nguoi_binh_luan INTEGER,
  ngay_binh_luan TEXT,
  noi_dung TEXT,
  sao_binh_luan INTEGER
);

